@page "/settings"
@using sv_194cf522de2f4991bc5daf416ccc9bf4.Models
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="settings-nav-item @(section == _activeSection ? "active" : "")"
                    @onclick="() => SetActiveSection(section)">
                    <span class="nav-icon">@GetSectionIcon(section)</span>
                    <span class="nav-label">@section</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_activeSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile Settings</h2>

                @if (_profileMessage is not null)
                {
                    <div class="toast-message success">@_profileMessage</div>
                }

                <div class="avatar-preview">
                    <img src="@_editProfile.AvatarUrl" alt="Avatar" class="avatar-img" />
                    <span class="avatar-url">@_editProfile.AvatarUrl</span>
                </div>

                <div class="form-group">
                    <label for="displayName">Display Name</label>
                    <input id="displayName" type="text" @bind="_editProfile.DisplayName" />
                </div>

                <div class="form-group">
                    <label for="email">Email</label>
                    <input id="email" type="email" @bind="_editProfile.Email" />
                </div>

                <div class="form-group">
                    <label for="bio">Bio</label>
                    <textarea id="bio" rows="4" @bind="_editProfile.Bio"></textarea>
                </div>

                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </section>
        }
        else if (_activeSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="_editNotifications.EmailNotifications" />
                        <span class="toggle-switch"></span>
                        <span>Email Notifications</span>
                    </label>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="_editNotifications.PushNotifications" />
                        <span class="toggle-switch"></span>
                        <span>Push Notifications</span>
                    </label>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="_editNotifications.WeeklyDigest" />
                        <span class="toggle-switch"></span>
                        <span>Weekly Digest</span>
                    </label>
                </div>

                <h3>Muted Channels</h3>
                <div class="channel-list">
                    @foreach (var channel in _allChannels)
                    {
                        <label class="channel-item">
                            <input type="checkbox"
                                   checked="@_editNotifications.MutedChannels.Contains(channel)"
                                   @onchange="e => ToggleMutedChannel(channel, (bool)e.Value!)" />
                            <span>@channel</span>
                        </label>
                    }
                </div>

                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                </div>
            </section>
        }
        else if (_activeSection == "Security")
        {
            <section class="settings-section">
                <h2>Security Settings</h2>

                <div class="expandable-panel">
                    <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                        <span>Change Password</span>
                        <span class="panel-toggle">@(_passwordPanelOpen ? "▲" : "▼")</span>
                    </button>

                    @if (_passwordPanelOpen)
                    {
                        <div class="panel-body">
                            @if (_passwordMessage is not null)
                            {
                                <div class="toast-message @(_passwordError ? "error" : "success")">@_passwordMessage</div>
                            }

                            <div class="form-group">
                                <label for="currentPassword">Current Password</label>
                                <input id="currentPassword" type="password" @bind="_currentPassword" />
                            </div>
                            <div class="form-group">
                                <label for="newPassword">New Password</label>
                                <input id="newPassword" type="password" @bind="_newPassword" />
                            </div>
                            <div class="form-group">
                                <label for="confirmPassword">Confirm Password</label>
                                <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                            </div>
                            <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                        </div>
                    }
                </div>

                <div class="security-item">
                    <div class="security-item-info">
                        <h3>Two-Factor Authentication</h3>
                        <span class="status-indicator @(_securitySettings?.TwoFactorEnabled == true ? "enabled" : "disabled")">
                            @(_securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <label class="toggle-label">
                        <input type="checkbox" checked="@(_securitySettings?.TwoFactorEnabled ?? false)" disabled />
                        <span class="toggle-switch"></span>
                    </label>
                </div>

                @if (_securitySettings?.LastPasswordChange is not null)
                {
                    <p class="last-password-change">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }

                <h3>Active Sessions</h3>
                <div class="sessions-table-wrapper">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @if (_securitySettings?.Sessions is not null)
                            {
                                @foreach (var session in _securitySettings.Sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td>
                                            @if (session.Id != _currentSessionId)
                                            {
                                                <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">
                                                    Revoke
                                                </button>
                                            }
                                            else
                                            {
                                                <span class="current-session-badge">Current</span>
                                            }
                                        </td>
                                    </tr>
                                }
                            }
                        </tbody>
                    </table>
                </div>

                @if (_sessionToRevoke is not null)
                {
                    <div class="modal-overlay" @onclick="CancelRevoke">
                        <div class="modal-dialog" @onclick:stopPropagation="true">
                            <h3>Confirm Session Revocation</h3>
                            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                            <div class="button-group">
                                <button class="btn btn-danger" @onclick="RevokeSession">Revoke Session</button>
                                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            </div>
                        </div>
                    </div>
                }
            </section>
        }
        else if (_activeSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>

                <div class="form-group">
                    <label>Theme</label>
                    <div class="radio-group">
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <label class="radio-label">
                                <input type="radio" name="theme" value="@theme"
                                       checked="@(_editAppearance.Theme == theme)"
                                       @onchange="() => _editAppearance.Theme = theme" />
                                <span>@theme</span>
                            </label>
                        }
                    </div>
                </div>

                <div class="form-group">
                    <label>Font Size</label>
                    <div class="radio-group">
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <label class="radio-label">
                                <input type="radio" name="fontSize" value="@size"
                                       checked="@(_editAppearance.FontSize == size)"
                                       @onchange="() => _editAppearance.FontSize = size" />
                                <span>@size</span>
                            </label>
                        }
                    </div>
                </div>

                <div class="form-group">
                    <label for="language">Language</label>
                    <select id="language" @bind="_editAppearance.Language">
                        <option value="English">English</option>
                        <option value="Spanish">Spanish</option>
                        <option value="French">French</option>
                        <option value="German">German</option>
                        <option value="Japanese">Japanese</option>
                    </select>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="_editAppearance.CompactMode" />
                        <span class="toggle-switch"></span>
                        <span>Compact Mode</span>
                    </label>
                </div>

                <h3>Live Preview</h3>
                <div class="live-preview @GetPreviewClasses()">
                    <div class="preview-header">Preview Header</div>
                    <div class="preview-body">
                        <p>This is how your content will look with the selected settings.</p>
                        <div class="preview-card">
                            <h4>Sample Card</h4>
                            <p>Theme: @_editAppearance.Theme | Font: @_editAppearance.FontSize | Language: @_editAppearance.Language</p>
                        </div>
                    </div>
                </div>

                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                </div>
            </section>
        }
    </main>
</div>

@code {
    private readonly string[] _sections = { "Profile", "Notifications", "Security", "Appearance" };
    private string _activeSection = "Profile";
    private readonly string _currentSessionId = "sess-1";

    // Profile state
    private ProfileEdit _editProfile = new();
    private UserProfile? _savedProfile;
    private string? _profileMessage;

    // Notifications state
    private NotificationEdit _editNotifications = new();
    private readonly List<string> _allChannels = new() { "general", "marketing", "announcements", "engineering", "design" };

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordMessage;
    private bool _passwordError;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private AppearanceEdit _editAppearance = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    private void SetActiveSection(string section)
    {
        _activeSection = section;
        _profileMessage = null;
    }

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    // Profile methods
    private async Task LoadProfile()
    {
        _savedProfile = await SettingsService.GetProfileAsync();
        _editProfile = new ProfileEdit
        {
            DisplayName = _savedProfile.DisplayName,
            Email = _savedProfile.Email,
            AvatarUrl = _savedProfile.AvatarUrl,
            Bio = _savedProfile.Bio
        };
    }

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_editProfile.DisplayName, _editProfile.Email, _editProfile.AvatarUrl, _editProfile.Bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _profileMessage = "Profile saved successfully!";
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            _editProfile = new ProfileEdit
            {
                DisplayName = _savedProfile.DisplayName,
                Email = _savedProfile.Email,
                AvatarUrl = _savedProfile.AvatarUrl,
                Bio = _savedProfile.Bio
            };
        }
        _profileMessage = null;
    }

    // Notifications methods
    private async Task LoadNotifications()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _editNotifications = new NotificationEdit
        {
            EmailNotifications = prefs.EmailNotifications,
            PushNotifications = prefs.PushNotifications,
            WeeklyDigest = prefs.WeeklyDigest,
            MutedChannels = new List<string>(prefs.MutedChannels)
        };
    }

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !_editNotifications.MutedChannels.Contains(channel))
            _editNotifications.MutedChannels.Add(channel);
        else if (!isMuted)
            _editNotifications.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(
            _editNotifications.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            new List<string>(_editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
    }

    // Security methods
    private async Task LoadSecurity()
    {
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task UpdatePassword()
    {
        _passwordMessage = null;
        _passwordError = false;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordMessage = "Current password is required.";
            _passwordError = true;
            return;
        }

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordMessage = "New password is required.";
            _passwordError = true;
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordMessage = "New password and confirmation do not match.";
            _passwordError = true;
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordMessage = "Password updated successfully!";
        await LoadSecurity();
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
            await LoadSecurity();
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} minutes ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    // Appearance methods
    private async Task LoadAppearance()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _editAppearance = new AppearanceEdit
        {
            Theme = settings.Theme,
            FontSize = settings.FontSize,
            Language = settings.Language,
            CompactMode = settings.CompactMode
        };
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_editAppearance.Theme, _editAppearance.FontSize, _editAppearance.Language, _editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_editAppearance.Theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_editAppearance.FontSize.ToLowerInvariant()}");
        if (_editAppearance.CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    // Mutable edit models
    private class ProfileEdit
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }

    private class NotificationEdit
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = new();
    }

    private class AppearanceEdit
    {
        public string Theme { get; set; } = "Light";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "English";
        public bool CompactMode { get; set; }
    }
}

